using HRIS.Api.DTOs.Letter; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace HRIS.Api.Controllers; [ApiController][Route("api/letters")][Authorize] public class LettersController:ControllerBase { private readonly ILetterService _service; public LettersController(ILetterService service)=>_service=service; [HttpGet("types")] public async Task<ActionResult<List<LetterTypeResponseDto>>> Types([FromQuery]bool includeInactive=false)=>Ok(await _service.GetTypesAsync(includeInactive)); [HttpPost("types")][Authorize(Roles="HR,Support")] public async Task<ActionResult<LetterTypeResponseDto>> CreateType(LetterTypeCreateDto dto)=>Ok(await _service.SaveTypeAsync(0,dto,User.ToUserContext())); [HttpPut("types/{id:int}")][Authorize(Roles="HR,Support")] public async Task<ActionResult<LetterTypeResponseDto>> UpdateType(int id,LetterTypeCreateDto dto)=>Ok(await _service.SaveTypeAsync(id,dto,User.ToUserContext())); [HttpGet] public async Task<ActionResult<List<LetterRequestResponseDto>>> Get()=>Ok(await _service.GetRequestsAsync(User.ToUserContext())); [HttpPost] public async Task<ActionResult<LetterRequestResponseDto>> Create(LetterRequestCreateDto dto)=>Ok(await _service.CreateAsync(dto,User.ToUserContext())); [HttpPost("{id:int}/issue")][Authorize(Roles="HR,Support")] public async Task<IActionResult> Issue(int id,[FromQuery]int documentId){await _service.IssueAsync(id,documentId,User.ToUserContext());return NoContent();} }
